import {cardLayout} from './card-layout.js?v=cards-8';
// Readable pages retain their original controls and saved game state.
const states=new WeakMap();let scheduled=false;
export function groupHeights(heights,limit){const pages=[];let page=[],used=0;for(let i=0;i<heights.length;i++){if(page.length&&used+heights[i]>limit){pages.push(page);page=[];used=0;}page.push(i);used+=heights[i];}if(page.length)pages.push(page);return pages;}
function blocksFrom(nodes){const result=[];for(const node of nodes){if(node.nodeType!==1){if(node.textContent.trim())result.push(node);continue;}if(node.matches('.panel,.puzzle-discovery,#bank-facts,.bank-fact,.cross-clues,.puzzle-answers,.reward-list')){result.push(...blocksFrom([...node.childNodes]));continue;}if(node.matches('.grid,.records')){const children=[...node.children];for(let i=0;i<children.length;i+=2){const row=node.cloneNode(false);row.removeAttribute('id');row.append(...children.slice(i,i+2));result.push(row);}continue;}if(node.matches('details')){const button=document.createElement('button');button.className='button secondary wide';button.textContent=node.querySelector('summary')?.textContent||'Read more';button.dataset.fitReading='true';button._reading=[...node.children].filter(n=>n.tagName!=='SUMMARY').map(n=>n.outerHTML).join('');result.push(button);continue;}result.push(node);}return result;}
function updatePager(host,state){state.pages.forEach((page,i)=>page.hidden=i!==state.index);state.previous.disabled=state.index===0;state.next.disabled=state.index===state.pages.length-1;state.label.textContent=`${state.index+1} / ${state.pages.length}`;}
function paginate(host,limit){if(!host)return;let state=states.get(host);if(!state||[...host.children].some(n=>!n.matches('.screen-page,.screen-pager'))){state={blocks:blocksFrom([...host.childNodes]),index:0};states.set(host,state);}else state.index=Math.max(0,state.index);
 const previousIndex=state.index;host.replaceChildren();host.classList.add('paged-content');host.style.setProperty('--page-space',`${limit}px`);const pages=[];let page;
 function newPage(){page=document.createElement('section');page.className='screen-page panel';host.append(page);pages.push(page);}
 newPage();for(const block of state.blocks){page.append(block);if(page.scrollHeight>limit&&page.children.length>1){newPage();page.append(block);}}
 const pager=document.createElement('nav');pager.className='screen-pager';pager.setAttribute('aria-label','Page navigation');const previous=document.createElement('button'),next=document.createElement('button'),label=document.createElement('span');previous.className=next.className='button secondary';previous.textContent='‹ Previous';next.textContent='Next ›';label.setAttribute('aria-live','polite');pager.append(previous,label,next);host.append(pager);state.pages=pages;state.previous=previous;state.next=next;state.label=label;state.index=Math.min(previousIndex,pages.length-1);previous.onclick=()=>{state.index--;updatePager(host,state);};next.onclick=()=>{state.index++;updatePager(host,state);};pager.hidden=pages.length===1;updatePager(host,state);
}
function fitPuzzle(host){host.classList.remove('paged-content');const stage=host.querySelector('.puzzle-stage'),space=stage?.querySelector('.puzzle-board-space');if(!space)return;const grid=space.firstElementChild;if(!grid)return;const styles=getComputedStyle(grid),cols=Number(styles.getPropertyValue('--cross-cols')||styles.getPropertyValue('--search-size')),rows=Number(styles.getPropertyValue('--cross-rows')||styles.getPropertyValue('--search-size'));const isWord=grid.id==='wordsearch-grid';const padding=isWord?12:8;const gap=isWord?2:0;const cell=Math.max(8,Math.floor(Math.min((space.clientWidth-padding-gap*(cols-1))/cols,(space.clientHeight-padding-gap*(rows-1))/rows)));grid.style.setProperty('--puzzle-cell',`${cell}px`);}
const observer=new MutationObserver(records=>{if(records.some(r=>r.target.id==='hub-content'||r.target.id==='modal-content'))queue();else queue();});
function observe(){for(const id of ['hub-content','modal-content','account-content']){const host=document.getElementById(id);if(host)observer.observe(host,{childList:true,subtree:true,characterData:true});}}
function layout(){scheduled=false;const focus=document.activeElement,selection=focus?.selectionStart,focusHost=focus?.closest?.('.paged-content'),focusNav=focus?.closest?.('.screen-pager')?(focus.textContent.includes('Next')?'next':'previous'):null;observer.disconnect();try{const height=window.visualViewport?.height||innerHeight;document.documentElement.style.setProperty('--visible-height',`${height}px`);const hub=document.getElementById('hub'),host=document.getElementById('hub-content');if(hub&&!hub.hidden&&host){if(host.querySelector('.pond-find-scene,.frog-trail-scene')){if(host.querySelector('.screen-page,.screen-pager')){const pages=[...host.querySelectorAll(':scope > .screen-page')];const nodes=pages.flatMap(page=>[...page.childNodes]);host.replaceChildren(...nodes);states.delete(host);}host.classList.remove('paged-content');host.style.removeProperty('--page-space');}else if(host.querySelector('.puzzle-stage'))fitPuzzle(host);else paginate(host,Math.max(80,host.clientHeight-50));}
 const modal=document.getElementById('modal'),content=document.getElementById('modal-content');if(modal?.open&&content){if(content.querySelector('.count')){content.classList.remove('paged-content');content.style.removeProperty('--page-space');}else paginate(content,Math.max(100,height-144));}const account=document.getElementById('account-dialog'),accountContent=document.getElementById('account-content');if(account?.open&&accountContent)paginate(accountContent,Math.max(100,height-120));if(document.body.classList.contains('playing')){const board=document.getElementById('board'),count=board.children.length,cols=Number(board.style.getPropertyValue('--cols'));const rows=Math.ceil(count/cols);board.style.setProperty('--rows',rows);if(cols>0&&rows>0){const style=getComputedStyle(board),gap=parseFloat(style.columnGap)||5,paddingX=(parseFloat(style.paddingLeft)||0)+(parseFloat(style.paddingRight)||0),paddingY=(parseFloat(style.paddingTop)||0)+(parseFloat(style.paddingBottom)||0);const size=cardLayout(board.clientWidth-paddingX+12,board.clientHeight-paddingY+12,cols,rows,gap);for(const [key,value] of Object.entries(size))board.style.setProperty('--card-'+key,value+'px');}}
 if(focusNav&&focusHost){states.get(focusHost)?.[focusNav]?.focus({preventScroll:true});}if(focus?.isConnected&&document.activeElement!==focus){focus.focus({preventScroll:true});if(typeof selection==='number')focus.setSelectionRange?.(selection,selection);}}finally{observe();}}
function queue(){if(!scheduled){scheduled=true;requestAnimationFrame(layout);}}
window.frogFitBoard=queue;
observe();new MutationObserver(queue).observe(document.body,{attributes:true,attributeFilter:['class']});for(const id of ['modal','account-dialog']){const el=document.getElementById(id);if(el)new MutationObserver(queue).observe(el,{attributes:true,attributeFilter:['open']});}
window.addEventListener('resize',queue);window.visualViewport?.addEventListener('resize',queue);document.addEventListener('click',e=>{const b=e.target.closest('[data-fit-reading]');if(b)window.frogReading?.(b._reading);});document.addEventListener('focusin',e=>{const page=e.target.closest('.screen-page');if(!page)return;const host=page.parentElement,state=states.get(host);if(state){state.index=state.pages.indexOf(page);updatePager(host,state);}});queue();

if('ResizeObserver' in window){const board=document.getElementById('board');if(board)new ResizeObserver(queue).observe(board);}
